import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.CGSzHL4z.js";const p=JSON.parse('{"title":"Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"reference/limits.md","filePath":"reference/limits.md","lastUpdated":1792705540000}'),s={name:"reference/limits.md"};function r(n,e,d,l,h,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><p>Some of AcesMotion&#39;s behaviour comes from Roblox itself. The table below pairs each engine limit with what AcesMotion does about it; the current limits of AcesMotion follow.</p><h2 id="engine-limitations-and-how-acesmotion-works-around-them" tabindex="-1">Engine limitations, and how AcesMotion works around them <a class="header-anchor" href="#engine-limitations-and-how-acesmotion-works-around-them" aria-label="Permalink to &quot;Engine limitations, and how AcesMotion works around them&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Roblox does this</th><th>So AcesMotion does this</th></tr></thead><tbody><tr><td>A joint&#39;s <code>Transform</code> never replicates between server and clients.</td><td>Every client evaluates joints itself. The server sends one message per play with the server clock instead of a stream of poses.</td></tr><tr><td>A Roblox animation holds one rig&#39;s joints and nothing else.</td><td>Cameras, parts, properties, sounds and effects play through the runtime from scene data. Joint-only scenes still export natively.</td></tr><tr><td>Studio&#39;s Animator samples a CurveAnimation 30 times a second.</td><td>Export defaults to KeyframeSequence, which plays every key exactly.</td></tr><tr><td>In edit mode a joint&#39;s Transform moves nothing until the Animator steps.</td><td>The preview steps the Animator after every pass so poses show while you scrub.</td></tr><tr><td><code>IKControl</code> doesn&#39;t solve in edit mode.</td><td>AcesMotion has its own IK solver, used for pins, context IK and every preview.</td></tr><tr><td>Studio&#39;s Move and Rotate tools rewrite a dragged part&#39;s Motor6D.</td><td>AcesMotion poses with its own gizmo and holds the viewport mouse while a scene is open.</td></tr><tr><td>Studio keeps Delete, Ctrl+C / V / X / D and a few others even while a plugin window has focus, and a plugin can&#39;t read global shortcut bindings.</td><td>Defaults avoid those keys (copy is <kbd>Shift+C</kbd>, paste <kbd>Shift+V</kbd>), and the Timeline sets Studio&#39;s selection aside while the pointer is over it, so a stray Delete can&#39;t remove your rig.</td></tr><tr><td>A plugin can&#39;t see keys held in its own window through <code>UserInputService:IsKeyDown</code>.</td><td>Modifiers come from each input event instead.</td></tr><tr><td>Studio&#39;s PluginMenu can&#39;t grey out or tick items.</td><td>AcesMotion draws its own menus, so every item can explain why it&#39;s disabled.</td></tr><tr><td>Studio&#39;s Undo discards every unrecorded change since the last step.</td><td>The preview rests the stand-ins around every undo step and poses them again after.</td></tr><tr><td>A Sound&#39;s <code>Play()</code> does nothing in edit mode.</td><td>The preview plays hidden AudioPlayer copies with the Sound&#39;s effects.</td></tr><tr><td>Studio can&#39;t fast-forward a particle emitter.</td><td>The preview shows frozen particle copies for the frame you&#39;re on.</td></tr><tr><td>Roblox&#39;s Animation Graph can&#39;t be authored by plugins.</td><td>Out of scope. Scenes and layers handle blending instead.</td></tr></tbody></table><h2 id="current-limits" tabindex="-1">Current limits <a class="header-anchor" href="#current-limits" aria-label="Permalink to &quot;Current limits&quot;">​</a></h2><h3 id="keys-and-focus" tabindex="-1">Keys and focus <a class="header-anchor" href="#keys-and-focus" aria-label="Permalink to &quot;Keys and focus&quot;">​</a></h3><p>Studio decides which keys reach a plugin, so a few can&#39;t be used or may clash.</p><h4 id="keys-studio-keeps" tabindex="-1">Keys Studio keeps <a class="header-anchor" href="#keys-studio-keeps" aria-label="Permalink to &quot;Keys Studio keeps&quot;">​</a></h4><ul><li>Studio keeps <kbd>Delete</kbd>, <kbd>Ctrl+C</kbd>, <kbd>Ctrl+V</kbd>, <kbd>Ctrl+X</kbd>, <kbd>Ctrl+D</kbd>, <kbd>Shift+X</kbd>, <kbd>O</kbd>, <kbd>,</kbd> and <kbd>.</kbd> for itself even while a plugin window has focus.</li><li>Any key bound in File &gt; Customize Shortcuts is global.</li><li>A plugin cannot read those bindings, so any default can clash on someone&#39;s machine. Rebind in Settings (four keys) or in Studio&#39;s shortcut editor.</li><li>If a Timeline key does nothing, the status bar says &quot;Click the Timeline first, then press the key again ({name}).&quot;</li><li>Studio&#39;s own <kbd>Ctrl+C</kbd>, <kbd>Ctrl+V</kbd>, <kbd>Ctrl+X</kbd>, <kbd>Ctrl+D</kbd>, <kbd>Ctrl+Z</kbd> and <kbd>Ctrl+Y</kbd> can&#39;t be given to an AcesMotion command (Studio takes them first).</li><li>Studio has no API for a plugin to open its File &gt; Customize Shortcuts editor.</li></ul><h4 id="focus" tabindex="-1">Focus <a class="header-anchor" href="#focus" aria-label="Permalink to &quot;Focus&quot;">​</a></h4><ul><li>The Timeline takes keyboard focus when the pointer enters it. After leaving it, Studio&#39;s <kbd>W</kbd> / <kbd>E</kbd> / <kbd>R</kbd> need a click in the viewport first.</li><li>On some setups a key may not reach the plugin: <ul><li>the Timeline taking focus on hover (its hover keys still work over it whichever window has focus)</li><li><kbd>Tab</kbd> (temporary pivot) in the viewport, since Studio&#39;s own draggers use it</li><li><kbd>J</kbd> over the viewport</li><li><kbd>Ctrl+Shift+O</kbd></li></ul></li><li>Studio installs can also bind keys like <kbd>I</kbd>, <kbd>K</kbd> and <kbd>V</kbd> to other actions, which is why the hold keys can be rebound.</li></ul><div class="warning custom-block"><p class="custom-block-title">Don&#39;t use Move or Rotate on a posed stand-in</p><p>Studio&#39;s own tools (Move, Rotate) rewrite the rig&#39;s joint offsets. Posing holds the mouse so that cannot happen by accident.</p></div><h4 id="settings-gaps" tabindex="-1">Settings gaps <a class="header-anchor" href="#settings-gaps" aria-label="Permalink to &quot;Settings gaps&quot;">​</a></h4><ul><li>Settings has no Navigation page yet (scroll and zoom presets). There is no UI for the zoom and pan bindings.</li><li>Settings &gt; Shortcuts lists keys only, not mouse gestures (scroll, drags). Those are on the <a href="/AcesMotion-docs/reference/gestures">Mouse gestures</a> page.</li><li>Crash recovery keeps one copy per scene (up to 20), written 2 s after each edit.</li><li>The recovery interval isn&#39;t a setting. How long copies are kept is (Settings &gt; Storage).</li></ul><h3 id="editor-limits" tabindex="-1">Editor limits <a class="header-anchor" href="#editor-limits" aria-label="Permalink to &quot;Editor limits&quot;">​</a></h3><p>The ranges and caps the editor enforces.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Range or cap</th></tr></thead><tbody><tr><td><strong>Editor windows</strong></td><td>6 per kind. The 7th is refused with &quot;Close an editor window first&quot;.</td></tr><tr><td>Sequence editor</td><td>20 points at most</td></tr><tr><td>Gradient editor</td><td>20 stops at most</td></tr><tr><td>Saved strip</td><td>64 colours, 32 gradients, 32 sequences</td></tr><tr><td>Saved names</td><td>Up to 24 characters</td></tr><tr><td>Sequence blending (two NumberSequences or ColorSequences)</td><td>Reads both at every keypoint time and keeps at most 20 points</td></tr><tr><td>Call count</td><td>1 to 50</td></tr><tr><td>Sound speed</td><td>0.25x to 4x (Ctrl stretch). A key can carry 0.05 to 20.</td></tr><tr><td>Sound row lanes</td><td>Up to 4 stacked</td></tr><tr><td>Row-height extra</td><td>0 to 240 px</td></tr><tr><td>Multi-edit</td><td>At most 500 objects</td></tr><tr><td>Zoom</td><td>0.01 to 64 px per frame</td></tr><tr><td>Snap distance</td><td>1 to 32 px</td></tr><tr><td>Onion Before / After</td><td>0 to 10 in Settings (1 to 5 in the menu)</td></tr><tr><td>Onion Step</td><td>1 to 120</td></tr><tr><td>Gizmo size</td><td>50 to 200%</td></tr><tr><td>Bone thickness, joint dot size</td><td>25 to 300%</td></tr><tr><td>Bone and joint dot transparency</td><td>0 to 90%</td></tr><tr><td>Trajectory line</td><td>1 to 8 px</td></tr><tr><td>Trajectory point size</td><td>50 to 300%</td></tr><tr><td>Motion trail</td><td>Every frame, up to 600 samples across all paths (longer spans sample every few frames)</td></tr></tbody></table><ul><li>Zoomed far out, a 30 minute scene at 60 fps fits in 1000 px. The ruler labels every 10,000 frames or 10 minutes if it has to.</li></ul><h4 id="roblox-animation-export" tabindex="-1">Roblox animation export <a class="header-anchor" href="#roblox-animation-export" aria-label="Permalink to &quot;Roblox animation export&quot;">​</a></h4><ul><li>A Roblox animation holds one rig and joints only.</li><li>Cameras, parts, property tracks, limb sizes, calls, attributes, root motion kept, modifiers and audio need the runtime. The export panel lists them.</li><li>Layers bake into the clip with <strong>Bake layers</strong> on, else the clip is Base alone.</li><li>Markers export natively (the payload as JSON text, 64 characters).</li></ul><div class="warning custom-block"><p class="custom-block-title">Curves are sampled</p><p><strong>Studio samples a CurveAnimation on a fixed 30 per second grid</strong>, so a Constant step or a 10 ms spike softens. KeyframeSequence (the default) plays every exported keyframe exactly.</p></div><h4 id="keying-and-posing" tabindex="-1">Keying and posing <a class="header-anchor" href="#keying-and-posing" aria-label="Permalink to &quot;Keying and posing&quot;">​</a></h4><ul><li>BrickColor, Font and PhysicalProperties values cannot be keyed.</li><li>Content properties are keyed through their ContentId twin.</li><li>CFrame properties are posed in the viewport (the Inspector shows a read-only position). CFrame attributes are editable.</li><li>Mirror: a joint whose rest frame does not mirror its partner&#39;s exactly is left out of Paste mirrored. The status line counts them.</li><li>IK limits cover elbows and knees only.</li><li>Resize works on parts and models, not rigs.</li><li>Limbs only ghosts cannot split a skinned mesh.</li></ul><h3 id="team-create" tabindex="-1">Team Create <a class="header-anchor" href="#team-create" aria-label="Permalink to &quot;Team Create&quot;">​</a></h3><ul><li>Only teammates who run AcesMotion show up. Someone without it is still in Studio&#39;s own collaborator list.</li><li>A teammate who stops sending (Studio froze, the connection dropped) disappears after 15 seconds.</li><li><strong>Ping</strong> sends your playhead time, but nothing shows it on the teammate&#39;s side yet.</li><li>Rings show up to 256 picked keys per teammate. Past that, their selection shows as one band per row.</li><li>If three people change the same actor within the same second, an edit can be dropped after three tries. Its toast says so; run it again.</li><li>A teammate previewing a property track and you editing that exact property in Studio&#39;s Properties window at the same moment: your change isn&#39;t keyed.</li></ul><h3 id="previews" tabindex="-1">Previews <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Previews&quot;">​</a></h3><p>What Studio&#39;s edit mode can&#39;t show exactly.</p><h4 id="effect-preview" tabindex="-1">Effect preview <a class="header-anchor" href="#effect-preview" aria-label="Permalink to &quot;Effect preview&quot;">​</a></h4><ul><li>Particles show as frozen copies on the frame you are on (Studio cannot fast-forward an emitter). The arrangement may re-roll when you pause.</li><li>While playing, real emitters run at 1x and slower. Above 1x or in reverse the frozen copies take over.</li><li>Flipbooks step through their frames by a render-by-render timing trick, so a frame can be one off now and then.</li><li>Particles only age on rendered frames, so check timing with the viewport showing.</li><li>A scrolling Beam holds still while scrubbing (Roblox restarts a Beam&#39;s scroll whenever its speed is set).</li><li>The preview cap (100 to 10,000, default <strong>1000</strong>) keeps every k-th particle. Real playback and games always show all.</li></ul><h4 id="trails-while-scrubbing" tabindex="-1">Trails while scrubbing <a class="header-anchor" href="#trails-while-scrubbing" aria-label="Permalink to &quot;Trails while scrubbing&quot;">​</a></h4><ul><li>Roblox draws a Trail only from where its attachments really moved.</li><li>So while you scrub, pause, play backward or faster than 1x, every Trail in the scene is drawn as a stand-in ribbon. It&#39;s built from where its two attachments were over its Lifetime: its colour, transparency and width over its life, its texture running the whole ribbon.</li><li>Playing forward at 1x or slower shows the real Trail again, started fresh.</li><li>A spawned actor&#39;s Trail stands in where its copy is now.</li></ul><h4 id="sounds" tabindex="-1">Sounds <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;Sounds&quot;">​</a></h4><ul><li>A Sound&#39;s own Play() does nothing in edit mode, so AcesMotion plays hidden AudioPlayer copies with the Sound&#39;s effects and SoundGroups.</li><li>The copies are 3D by default, flat with &quot;Play sounds in 2D while animating&quot;.</li><li>While scrubbing only short snippets play, not continuous audio.</li><li><strong>Waveforms</strong> are read in 2 second chunks as they scroll into view.</li><li>A sound&#39;s length arrives in about half a second. Until then its bar is a short placeholder.</li><li>The Loading spinner on sound bars does not spin.</li></ul><h4 id="markers" tabindex="-1">Markers <a class="header-anchor" href="#markers" aria-label="Permalink to &quot;Markers&quot;">​</a></h4><ul><li>Marker payloads cannot be edited in the UI yet (they come from imports).</li></ul>',35)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
